class Solution {
public:
    vector<int> parent;
    vector<int> rank_;
    vector<int> compAnd;

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y, int w) {
        int px = find(x);
        int py = find(y);
        if (px == py) {
            compAnd[px] &= w;
            return;
        }
        if (rank_[px] < rank_[py]) {
            int tmp = px;
            px = py;
            py = tmp;
        }
        parent[py] = px;
        compAnd[px] &= compAnd[py];
        compAnd[px] &= w;
        if (rank_[px] == rank_[py]) {
            rank_[px]++;
        }
    }

    vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        parent.resize(n);
        rank_.resize(n, 0);
        compAnd.resize(n, ~0);

        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        for (auto& e : edges) {
            unite(e[0], e[1], e[2]);
        }

        vector<int> ans;
        ans.reserve(query.size());
        for (auto& q : query) {
            int ps = find(q[0]);
            int pt = find(q[1]);
            if (ps != pt) {
                ans.push_back(-1);
            } else {
                ans.push_back(compAnd[ps]);
            }
        }
        return ans;
    }
};
